SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',v.relname,'kind',v.relkind,'updatable_mask',pg_relation_is_updatable(v.oid,true),'anon_write',has_table_privilege('anon',v.oid,'UPDATE,INSERT,DELETE'),'authenticated_write',has_table_privilege('authenticated',v.oid,'UPDATE,INSERT,DELETE'),'rules',(SELECT coalesce(jsonb_agg(pg_get_ruledef(r.oid) ORDER BY rulename),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class=v.oid AND r.rulename<>'_RETURN')) ORDER BY n.nspname,v.relname),'[]'::jsonb) AS evidence FROM pg_class v JOIN pg_namespace n ON n.oid=v.relnamespace WHERE v.relkind IN('v','m') AND v.oid IN(SELECT rw.ev_class FROM pg_depend dep JOIN pg_rewrite rw ON rw.oid=dep.objid WHERE dep.refobjid='public.users'::regclass);
